package exercise

import (
	"math"
	"reflect"
	"testing"
)

const inf = math.MaxInt

func TestBellmanFordDistances(t *testing.T) {
	cases := []struct {
		name  string
		n     int
		edges []Edge
		src   int
		want  []int
	}{
		{
			name:  "negative edge shortens a path",
			n:     5,
			edges: []Edge{{0, 1, 5}, {1, 2, 1}, {1, 3, 2}, {2, 4, 1}, {4, 3, -1}},
			src:   0,
			want:  []int{0, 5, 6, 6, 7},
		},
		{
			name:  "negative edge outside any cycle",
			n:     3,
			edges: []Edge{{0, 1, 4}, {0, 2, 5}, {2, 1, -3}},
			src:   0,
			want:  []int{0, 2, 5},
		},
		{
			name:  "edges listed against the path need every round",
			n:     5,
			edges: []Edge{{3, 4, -1}, {2, 3, -1}, {1, 2, -1}, {0, 1, -1}},
			src:   0,
			want:  []int{0, -1, -2, -3, -4},
		},
		{
			name:  "cycle adding up to zero is not negative",
			n:     3,
			edges: []Edge{{0, 1, 1}, {1, 2, 2}, {2, 1, -2}},
			src:   0,
			want:  []int{0, 1, 3},
		},
		{
			name:  "unreachable negative cycle does not count",
			n:     4,
			edges: []Edge{{0, 1, 2}, {2, 3, 1}, {3, 2, -3}},
			src:   0,
			want:  []int{0, 2, inf, inf},
		},
		{
			name:  "edges only go one way",
			n:     2,
			edges: []Edge{{1, 0, 3}},
			src:   0,
			want:  []int{0, inf},
		},
		{
			name:  "different source",
			n:     5,
			edges: []Edge{{0, 1, 5}, {1, 2, 1}, {1, 3, 2}, {2, 4, 1}, {4, 3, -1}},
			src:   1,
			want:  []int{inf, 0, 1, 1, 2},
		},
		{
			name: "single vertex",
			n:    1,
			src:  0,
			want: []int{0},
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got, ok := BellmanFord(c.n, c.edges, c.src)
			if !ok {
				t.Fatalf("reported a negative cycle, but there is none reachable from %d", c.src)
			}
			if !reflect.DeepEqual(got, c.want) {
				t.Errorf("got %v, want %v", got, c.want)
			}
		})
	}
}

func TestBellmanFordNegativeCycle(t *testing.T) {
	cases := []struct {
		name  string
		n     int
		edges []Edge
		src   int
	}{
		{
			name:  "cycle 1-2-3 adds up to -3",
			n:     4,
			edges: []Edge{{0, 1, 4}, {1, 2, -6}, {2, 3, 5}, {3, 1, -2}},
			src:   0,
		},
		{
			name:  "negative edge from a vertex to itself",
			n:     2,
			edges: []Edge{{0, 1, 1}, {1, 1, -1}},
			src:   0,
		},
		{
			name:  "cycle at the end of a long chain listed backwards",
			n:     5,
			edges: []Edge{{4, 3, -2}, {3, 4, 1}, {2, 3, 1}, {1, 2, 1}, {0, 1, 1}},
			src:   0,
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got, ok := BellmanFord(c.n, c.edges, c.src)
			if ok {
				t.Fatalf("got %v, true; want a reported negative cycle (nil, false)", got)
			}
			if got != nil {
				t.Errorf("got distances %v alongside false, want nil", got)
			}
		})
	}
}

