package exercise

import "math"

type Edge struct {
	From   int
	To     int
	Weight int
}

func BellmanFord(n int, edges []Edge, src int) ([]int, bool) {
	dist := make([]int, n)
	for i := range dist {
		dist[i] = math.MaxInt
	}
	dist[src] = 0

	for i := 0; i < n-1; i++ {
		for _, e := range edges {
			if dist[e.From] != math.MaxInt && dist[e.From]+e.Weight < dist[e.To] {
				dist[e.To] = dist[e.From] + e.Weight
			}
		}
	}

	for _, e := range edges {
		if dist[e.From] != math.MaxInt && dist[e.From]+e.Weight < dist[e.To] {
			return nil, false
		}
	}
	return dist, true
}
